import numpy as np
from scipy.stats import norm

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def swish(x):
    return x * sigmoid(x)

def relu(x):
    return np.maximum(0, x)

def gelu_exact(x):
    return x * norm.cdf(x)

test_inputs = np.array([-2.0, -0.5, -0.1, 0.0, 0.5, 2.0])

print("Input | ReLU | GELU | Swish")
for x in test_inputs:
    print(f"  {x:5.2f} | {relu(x):5.2f} | {gelu_exact(x):7.4f} | {swish(x):7.4f}")

max_diff = np.max(np.abs(swish(test_inputs) - gelu_exact(test_inputs)))
print(f"\nMaximum difference between Swish and GELU across these inputs: {max_diff:.4f}")
print("Notice how genuinely close the two curves are, despite arriving from entirely different mathematical derivations")
